<script setup lang="ts">
import RemoteMap from '../components/RemoteMap.vue';
import {computed,ref} from 'vue';
import {usePlatform} from '../stores/platform';import {apiMode} from '../api/client';import {filterRows,dataTypes} from '../domain';import type {Field} from '../domain';
import QueryForm from '../components/QueryForm.vue';import DeviceMap from '../components/DeviceMap.vue';import DataTable from '../components/DataTable.vue';import ChartPanel from '../components/ChartPanel.vue';
const p=usePlatform(),map=ref<InstanceType<typeof DeviceMap>>(),timeline=ref(0);const distribution=computed(()=>p.active==='设备分布');
const devices=computed(()=>p.filterRows(p.db.devices.filter(d=>apiMode==='http'||p.superuser||p.visibleSites.some(s=>s.name===d.site)),p.f,{site:d=>d.site,status:d=>d.status,keyword:d=>d.name+' '+d.serial,sites:d=>d.site,devices:d=>d.id}));
const selected=computed(()=>devices.value.filter(d=>p.mapSelected.includes(d.id)));
const fields=computed<Field[]>(()=>distribution.value?[{key:'sites',label:'场所',options:p.visibleSites.map(s=>s.name),multiple:true},{key:'devices',label:'设备',options:p.db.devices.map(d=>({label:d.name,value:d.id})),multiple:true},{key:'status',label:'在线状态',options:['全部','在线','离线']},{key:'keyword',label:'设备关键字'}]:[{key:'type',label:'数据类型',options:[...dataTypes,'综合']},{key:'site',label:'场所',options:['全部',...p.visibleSites.map(s=>s.name)]},{key:'start',label:'采集开始',type:'datetime-local'},{key:'end',label:'采集结束',type:'datetime-local'},{key:'target',label:'IMSI / 车牌 / MAC / 人像'},{key:'imei',label:'IMEI'}]);
const rows=computed(()=>p.filterRows(p.captureRows(p.f.type==='综合'?undefined:String(p.f.type||'电围')),p.f,{site:r=>r.site,start:r=>r.time,end:r=>r.time,target:r=>r.target,imei:r=>r.imei}).sort((a,b)=>a.time.localeCompare(b.time)));
const person=computed(()=>p.db.people.find(person=>person.id===rows.value[0]?.person));const personCaptures=computed(()=>rows.value.filter(c=>c.person===person.value?.id));
const trajectory=computed(()=>p.mapTrajectory?rows.value.slice(0,timeline.value||rows.value.length).map(c=>c.deviceId):[]);
const rates=computed(()=>[...new Set(p.db.sites.map(s=>s.region))].map(region=>{const ds=devices.value.filter(d=>d.region===region);return {日期:region,在线率:ds.length?Math.round(ds.filter(d=>d.status==='在线').length/ds.length*100):0};}));
function reset(){p.reset();p.mapSelected=[];p.mapTrajectory=false;timeline.value=0;map.value?.reset();}
</script>
<template><RemoteMap v-if="apiMode==='http'"/><template v-else><QueryForm :fields="fields" :model="p.f" @search="p.query" @reset="reset"/><div class="query-split"><div class="stack"><DeviceMap ref="map" :devices="devices" :selected="p.mapSelected" :distribution="distribution" :trajectory="trajectory" @select="p.mapSelected=$event" @reset="p.mapTrajectory=false;timeline=0"/><ChartPanel v-if="distribution" title="区域设备在线率" :rows="rates" :labels="['在线率']" unit="%"/><DataTable v-else :rows="rows" :columns="[{key:'time',label:'采集时间'},{key:'type',label:'类型'},{key:'target',label:'目标标识'},{key:'site',label:'场所'},{key:'device',label:'设备',link:true}]" @select="p.chosen=$event" @open="row=>p.deviceInfo(String(row.deviceId))"><template #actions><el-button @click="p.mapTrajectory=!p.mapTrajectory;timeline=0">展示轨迹</el-button></template></DataTable><section v-if="p.mapTrajectory&&!distribution" class="card"><h3>轨迹时间轴</h3><el-slider v-model="timeline" :min="0" :max="rows.length"/><p>{{rows[Math.max(0,timeline-1)]?.time}} · {{rows[Math.max(0,timeline-1)]?.site}}</p><el-button @click="timeline=Math.min(rows.length,timeline+1)">下一点</el-button></section></div><aside class="stack"><section class="card"><h3>已选设备</h3><el-empty v-if="!selected.length" description="请框选或单选地图设备" :image-size="80"/><article v-for="d in selected" :key="d.id" class="selected-device"><el-button link type="primary" @click="p.deviceInfo(d.id)">{{d.name}}</el-button><p>{{d.site}} · {{d.status}}</p></article><div class="actions"><template v-if="distribution"><el-button :disabled="!selected.length" @click="p.navigate('场所管理',{ids:selected.map(d=>p.db.sites.find(s=>s.name===d.site)?.id||'')})">场所详情</el-button><el-button :disabled="!selected.length" @click="p.navigate('设备管理',{ids:selected.map(d=>d.id)})">设备详情</el-button></template><template v-else><el-button :disabled="!selected.length" @click="p.formAnalysis('区域统计',undefined,rows.filter(r=>p.mapSelected.includes(r.deviceId)))">区域统计</el-button><el-button :disabled="!selected.length" @click="p.formAnalysis('伴随任务',undefined,rows.filter(r=>p.mapSelected.includes(r.deviceId)))">伴随分析</el-button></template></div></section><section v-if="person&&!distribution" class="card person-info"><h3>目标基本信息</h3><img :src="person.image" alt="人物画像"/><dl><dt>姓名</dt><dd>{{person.name}}</dd><dt>性别</dt><dd>{{person.sex}}</dd><dt>民族</dt><dd>{{person.ethnic}}</dd><dt>手机号码</dt><dd>{{person.phone}}</dd><dt>身份证号码</dt><dd>{{person.identity}}</dd><dt>常驻地区</dt><dd>{{person.resident}}</dd><dt>疑似落脚点</dt><dd>{{person.landing}}</dd><dt>外貌特征</dt><dd>{{person.appearance}}</dd><dt>被设备捕捉次数</dt><dd>{{personCaptures.length}}</dd><dt>经过站点次数</dt><dd>{{new Set(personCaptures.map(c=>c.site)).size}}</dd><dt>经过区域</dt><dd>{{[...new Set(personCaptures.map(c=>c.region))].join('、')}}</dd></dl></section></aside></div></template></template>

